-- 27. UPDATE PROJECT PROGRESS (computed from task averages)
-- ============================================================
UPDATE `project` p SET p.`progress` = (SELECT COALESCE(AVG(t.`progress`), 0) FROM `task` t WHERE t.`project_id` = p.`id`);

SET FOREIGN_KEY_CHECKS = 1;

